# Adding or removing a passkey asks for a recent sign-in (generated by
# maquina:passkeys).
#
# A passkey added from a stolen session cookie would outlive the cookie, so
# a session older than REAUTHENTICATE_AFTER is ended and the person signs in
# again (email code or passkey), coming back to the passkeys page after.
module PasskeyReauthentication
  extend ActiveSupport::Concern

  REAUTHENTICATE_AFTER = 30.minutes

  private

  def require_recent_sign_in
    return if Current.session.created_at.after?(REAUTHENTICATE_AFTER.ago)

    terminate_session
    session[:return_to_after_authenticating] = passkeys_url
    flash[:alert] = t("flash.passkeys.reauthenticate")

    respond_to do |format|
      format.html { redirect_to new_session_path }
      format.json { render json: {redirect_url: new_session_url}, status: :unauthorized }
    end
  end
end
